import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.BeforeEach;
import static org.junit.jupiter.api.Assertions.*;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

// Covers the real textures generated by the two persistent rollout
// buttons uiRollout.pde labels "SOLARCHVISION current viewport" and
// "SOLARCHVISION all sections" (see UI_rolloutTest.java's own
// renderViewportButtonBounds/renderSectionsButtonBounds section for the
// click-handling side of those two).
//
// Neither button's own underlying computation - preBakeViewport()/
// calculate_VertexSolar_array() for the first, render_ShadowsOnSections()/
// calculate_ImpactOnSections() -> calculate_Impact_CurrentPreBaked() for
// the second - is itself callable headlessly here: UI_rolloutTest.java's
// own class comment on handleRenderSectionsButtonClick() documents
// exactly why (cursor()/loadImage() calls that throw outside a real
// running sketch), and preBakeViewport3D.pde's own canShowProgressWindow()
// comment documents the same for the viewport side. So, same approach as
// everywhere else in this suite that's hit that wall (ExportObjectsOBJTest.
// java's own comment on exportObj() for the general pattern): this file
// sets up the STATE those computations would have left behind - real,
// non-placeholder PImages painted into allSections.SolidImpact/SolarImpact,
// confirmed by hand to be exactly the shape calculate_Impact_
// CurrentPreBaked() itself leaves (createImage(RES1, RES2, RGB) replacing
// the small 2x2 placeholder - see that method's own
// "allSections.SolarImpact[f][j + 1][q] = createImage(...)" line,
// solarImpacts.pde) - and tests the part that's actually at risk of
// regressing on its own: that saveProject()/load_project() correctly
// persist and restore those images as real files on disk, in a genuinely
// fresh solarchvision_bim() instance, not just left-over in-memory state.
//
// "SOLARCHVISION current viewport" itself turns out to have no texture of
// its own to persist - confirmed directly against the real compiled app:
// clicking it only ever changes STUDY.impactGraphIndex (via
// setimpactGraphIndex(), mouseClicked.pde), a plain scalar STUDY.to_XML()/
// from_XML() already round-trips - so that's what this file's own
// "viewport" test below actually checks, alongside the section textures
// the other tests focus on.
//
// Every load_project() call below hits the same known
// update_frame_layout() NullPointerException FileSelectedTest.java's own
// class comment documents - confirmed by hand, same as that file and
// LoadProjectTest.java, that every from_XML() (including allSections' own
// texture loading) completes first.
class SaveLoadSectionTexturesTest {

  private solarchvision_bim app;

  @BeforeEach
  void setUp () throws java.io.IOException {
    app = new solarchvision_bim();
    app.Terrain.Mesh = new float[app.Terrain.rowCount][app.Terrain.columnCount][3];
    // See Earth3DTest.java's own comment on why this isn't
    // app.locateBaseFolder().
    app.BaseFolder = java.nio.file.Files.createTempDirectory("solarchvision-bim-test").toString();
    app.sketchPath(); // side effect: lazily caches into PApplet's own sketchPath field, which loadStrings()/loadImage()/createInput() check directly - without this they throw "Files must be loaded inside setup() or after it has been called." even though BaseFolder above is already set
    app.update_project_folders(); // Folder_Project is null until this runs
    // See SaveProjectTest.java's/LoadProjectTest.java's own identical
    // comment: load_project()'s own update_station(1..4) needs
    // Folder_climateTypicalYear/.../Folder_ensembleObservation, which
    // only update_input_folders() ever sets.
    app.update_input_folders();
  }

  // A fresh solarchvision_bim() instance, set up the exact same way as
  // app (same BaseFolder - i.e. "reopen the same project" after closing
  // the app entirely, not "open a copy of it somewhere else"), standing
  // in for a genuinely new session rather than the same instance with
  // its fields manually cleared (the pattern SaveProjectTest.java/
  // FileSelectedTest.java/LoadProjectTest.java all otherwise use) - this
  // is the part that's actually new here: nothing about these textures'
  // own in-memory PImage objects could possibly leak between app and
  // this one.
  private solarchvision_bim freshSession () throws IOException {
    solarchvision_bim app2 = new solarchvision_bim();
    app2.Terrain.Mesh = new float[app2.Terrain.rowCount][app2.Terrain.columnCount][3];
    app2.BaseFolder = app.BaseFolder;
    app2.sketchPath();
    app2.update_project_folders();
    app2.update_input_folders();
    return app2;
  }

  private void loadExpectingTheKnownFrameLayoutNPE (solarchvision_bim target, Path file) {
    Throwable thrown = null;
    try {
      target.load_project(file.toString());
    } catch (Throwable t) {
      thrown = t;
    }
    assertInstanceOf(NullPointerException.class, thrown, "update_frame_layout()'s own graphics setup is expected to still throw here");
  }

  private processing.core.PImage solidColorImage (int w, int h, int r, int g, int b) {
    processing.core.PImage img = app.createImage(w, h, app.RGB);
    img.loadPixels();
    int c = app.color(r, g, b);
    for (int i = 0; i < img.pixels.length; i++) img.pixels[i] = c;
    img.updatePixels();
    return img;
  }

  private Path saveToTempFile (String prefix) throws IOException {
    Path saved = Files.createTempFile(prefix, ".xml");
    Files.delete(saved); // only the containing directory needs to pre-exist - see
                          // FileSelectedTest.java's own identical reasoning.
    app.saveProject(saved.toString());
    return saved;
  }

  // ================= "SOLARCHVISION all sections" - SolidImpact =========

  @Test
  void savingASection_withARenderedSolidImpactTexture_writesARealBmpFile_withTheRightPixels () throws IOException {
    app.allSections.create(0, 0, 0, 5, 1, 1, 1, 4, 4);
    app.allSections.SolidImpact[0] = solidColorImage(4, 4, 10, 20, 30);

    Path saved = saveToTempFile("save-load-textures-solidimpact-file-test");

    Path textureFile = Path.of(app.Folder_Project, "Textures", "SolidImpact_0.bmp");
    assertTrue(Files.exists(textureFile), "expected " + textureFile + " to exist");
    assertTrue(Files.size(textureFile) > 0);

    // Read it back as a plain file, independent of anything load_project()
    // itself does later - this confirms the SAVE side wrote a real,
    // correctly-colored image, not just that some bytes landed on disk.
    processing.core.PImage reloaded = app.loadImage(textureFile.toString());
    assertNotNull(reloaded);
    assertEquals(4, reloaded.width);
    assertEquals(4, reloaded.height);
    reloaded.loadPixels();
    assertEquals(app.color(10, 20, 30), reloaded.pixels[0]);
  }

  @Test
  void loadProject_inAFreshSession_restoresASectionsSolidImpactTexture_pixelForPixel () throws IOException {
    app.allSections.create(0, 0, 0, 5, 1, 1, 1, 4, 4);
    app.allSections.SolidImpact[0] = solidColorImage(4, 4, 10, 20, 30);

    Path saved = saveToTempFile("save-load-textures-solidimpact-fresh-test");

    solarchvision_bim app2 = freshSession();
    loadExpectingTheKnownFrameLayoutNPE(app2, saved);

    assertEquals(1, app2.allSections.num);
    processing.core.PImage restored = app2.allSections.SolidImpact[0];
    assertEquals(4, restored.width);
    assertEquals(4, restored.height);
    restored.loadPixels();
    assertEquals(app2.color(10, 20, 30), restored.pixels[0], "the exact painted color should have survived the round trip through a real file, in a brand new app instance");
  }

  // ================= "SOLARCHVISION all sections" - SolarImpact ==========

  @Test
  void loadProject_inAFreshSession_restoresASectionsSolarImpactTexture_includingItsRealResolution () throws IOException {
    // Mirrors exactly what calculate_Impact_CurrentPreBaked() itself does
    // (solarImpacts.pde's own "allSections.SolarImpact[f][j + 1][q] =
    // createImage(this.RES1, this.RES2, RGB)" line) - replacing the
    // small 2x2 placeholder allSections.create() seeds every slot with
    // (sections.pde's own comment on that) with a real, full-resolution
    // image for the one (day, variation) slot that was actually baked.
    app.allSections.create(0, 0, 0, 5, 1, 1, 1, 8, 6);
    int dayIndex = 1; // STUDY.startDay + 1, same as the production loop's own "j + 1"
    int activeVariation = 0;
    assertEquals(2, app.allSections.SolarImpact[0][dayIndex].length, "sanity check, not the point of this test"); // numberOfImpactVariations
    assertEquals(2, app.allSections.SolarImpact[0][dayIndex][activeVariation].width, "sanity check: still the small placeholder before this test paints over it");

    app.allSections.SolarImpact[0][dayIndex][activeVariation] = solidColorImage(8, 6, 40, 50, 60);

    Path saved = saveToTempFile("save-load-textures-solarimpact-fresh-test");

    solarchvision_bim app2 = freshSession();
    loadExpectingTheKnownFrameLayoutNPE(app2, saved);

    processing.core.PImage restored = app2.allSections.SolarImpact[0][dayIndex][activeVariation];
    assertEquals(8, restored.width, "the real baked resolution, not the 2x2 placeholder");
    assertEquals(6, restored.height);
    restored.loadPixels();
    assertEquals(app2.color(40, 50, 60), restored.pixels[0]);

    // A slot that was never painted (still the placeholder) should still
    // round-trip cleanly too - every ni*nj*nk slot gets its own saved/
    // reloaded file regardless (sections.pde's own to_XML()/from_XML()
    // loops), not just the one this test painted.
    processing.core.PImage stillPlaceholder = app2.allSections.SolarImpact[0][dayIndex][1 - activeVariation];
    assertEquals(2, stillPlaceholder.width);
    assertEquals(2, stillPlaceholder.height);
  }

  @Test
  void loadProject_inAFreshSession_keepsEachSectionsTexturesSeparate_acrossMultipleSections () throws IOException {
    // The SolarImpact flattened index ((i * nj + j) * nk + k), computed
    // directly in sections.pde's own to_XML()/from_XML(), is exactly the
    // kind of arithmetic that's easy to get subtly wrong (e.g. swapping
    // ni/nj's own roles) without it showing up at all on a single-section
    // fixture like the tests above - two sections, each with a distinct
    // SolidImpact color, is what actually exercises it.
    app.allSections.create(0, 0, 0, 5, 1, 1, 1, 4, 4);
    app.allSections.create(10, 0, 0, 5, 1, 1, 1, 4, 4);
    app.allSections.SolidImpact[0] = solidColorImage(4, 4, 255, 0, 0);
    app.allSections.SolidImpact[1] = solidColorImage(4, 4, 0, 255, 0);
    app.allSections.SolarImpact[0][1][0] = solidColorImage(4, 4, 255, 255, 0);
    app.allSections.SolarImpact[1][1][0] = solidColorImage(4, 4, 0, 255, 255);

    Path saved = saveToTempFile("save-load-textures-multisection-fresh-test");

    solarchvision_bim app2 = freshSession();
    loadExpectingTheKnownFrameLayoutNPE(app2, saved);

    assertEquals(2, app2.allSections.num);

    app2.allSections.SolidImpact[0].loadPixels();
    app2.allSections.SolidImpact[1].loadPixels();
    assertEquals(app2.color(255, 0, 0), app2.allSections.SolidImpact[0].pixels[0]);
    assertEquals(app2.color(0, 255, 0), app2.allSections.SolidImpact[1].pixels[0]);

    app2.allSections.SolarImpact[0][1][0].loadPixels();
    app2.allSections.SolarImpact[1][1][0].loadPixels();
    assertEquals(app2.color(255, 255, 0), app2.allSections.SolarImpact[0][1][0].pixels[0]);
    assertEquals(app2.color(0, 255, 255), app2.allSections.SolarImpact[1][1][0].pixels[0]);
  }

  // ================= "SOLARCHVISION current viewport" ====================

  @Test
  void loadProject_inAFreshSession_restoresTheSkinPotentialSelection_setByTheViewportButtonsOwnAction () throws IOException {
    // The one bit of state "SOLARCHVISION current viewport" actually
    // leaves behind for a project to persist - see this file's own
    // header comment on why there's no image/texture of its own here,
    // unlike the "all sections" button covered above. Calls the real
    // production function (setimpactGraphIndex(), mouseClicked.pde)
    // rather than poking STUDY.impactGraphIndex directly, the same way
    // putAction("Skin Potential (Active)"/"(Passive)") itself does
    // (actions.pde).
    app.setimpactGraphIndex(app.impactGraphIndex_URBAN_ACTIVE, false);

    Path saved = saveToTempFile("save-load-textures-viewport-fresh-test");

    solarchvision_bim app2 = freshSession();
    loadExpectingTheKnownFrameLayoutNPE(app2, saved);

    assertEquals(app.impactGraphIndex_URBAN_ACTIVE, app2.STUDY.impactGraphIndex);
  }
}
